@Service @RequiredArgsConstructor @Transactional(isolation=Isolation.READ_COMMITTED)
public class OrdersService {
 private final CollaborationStore x;
 public List<Map<String,Object>> mappings(Context a){x.buyer(a);return x.db.queryForList("SELECT m.CONNECTOR_ID AS connectorId,m.EXTERNAL_KEY AS externalKey,m.SUPPLIER_ID AS supplierId,m.ORG_ID AS orgId,s.NAME AS supplierName,c.MODE AS mode FROM SRM_COL_SUPPLIER_MAP m JOIN SRM_SUPPLIER s ON s.ID=m.SUPPLIER_ID JOIN SRM_XCH_CONNECTOR c ON c.ID=m.CONNECTOR_ID WHERE m.ORG_ID=? ORDER BY m.EXTERNAL_KEY",a.orgId());}
 public void map(Context a,Mapping p){require(!a.portal()&&x.has(a,"SYS-ADMIN","superAdmin"),403,"仅系统管理员可配置ERP供方映射");var s=x.access.requireSupplier(a,p.supplierId(),true);require(s.orgId().equals(a.orgId()),403,"只能映射当前组织供方");var c=x.db.queryForMap("SELECT MODE FROM SRM_XCH_CONNECTOR WHERE ID=?",p.connectorId());x.exchange.requireTarget(p.connectorId(),a.orgId(),"ERP",s(c,"MODE"));var old=x.db.queryForList("SELECT SUPPLIER_ID FROM SRM_COL_SUPPLIER_MAP WHERE CONNECTOR_ID=? AND EXTERNAL_KEY=? FOR UPDATE",p.connectorId(),p.externalKey());require(old.isEmpty()||p.supplierId().equals(old.get(0).get("SUPPLIER_ID")),409,"已使用的外部供方标识不能静默改绑");x.db.update("INSERT IGNORE INTO SRM_COL_SUPPLIER_MAP(CONNECTOR_ID,EXTERNAL_KEY,ORG_ID,SUPPLIER_ID,CREATED_BY,CREATED_AT) VALUES(?,?,?,?,?,NOW(3))",p.connectorId(),p.externalKey(),a.orgId(),p.supplierId(),a.userId());x.audit(a,p.supplierId(),p.connectorId(),"ERP_SUPPLIER_MAPPED",Map.of("externalKey",p.externalKey()));}
 public Map<String,Object> sourcePo(Origin origin,Command event){SourcePo p=x.input(event.data(),SourcePo.class);require(origin.system().equals("ERP"),403,"PO只能来自ERP连接");var mapped=x.db.queryForList("SELECT SUPPLIER_ID FROM SRM_COL_SUPPLIER_MAP WHERE CONNECTOR_ID=? AND EXTERNAL_KEY=? AND ORG_ID=?",origin.connectorId(),p.supplierKey(),origin.orgId());if(mapped.isEmpty())throw new PendingDependency("SUPPLIER_MAPPING_REQUIRED");Context a=x.system(origin);String sid=s(mapped.get(0),"SUPPLIER_ID");var supplier=x.access.requireSupplier(a,sid,true);var prior=x.db.queryForList("SELECT * FROM SRM_COL_PO WHERE CONNECTOR_ID=? AND EXTERNAL_KEY=? FOR UPDATE",origin.connectorId(),event.businessKey());boolean fresh=prior.isEmpty();if(fresh)x.eligibility.requireEligibleForNewBusiness(sid,origin.orgId());String pid=fresh?id():s(prior.get(0),"ID");var old=fresh?null:prior.get(0);if(old!=null){require(sid.equals(old.get("SUPPLIER_ID"))&&p.poNo().equals(old.get("PO_NO"))&&origin.mode().equals(old.get("MODE")),409,"PO身份或供方不能改绑");require(event.version()==n(old,"SOURCE_VERSION")+1,409,"PO来源版本冲突");if(!p.currency().equals(old.get("CURRENCY")))require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_ASN WHERE PO_ID=?",Long.class,pid)==0,409,"已有履约记录的订单不能更换币种");}
  var existing=new HashMap<String,Map<String,Object>>();if(!fresh)for(var row:x.db.queryForList("SELECT * FROM SRM_COL_PO_LINE WHERE PO_ID=? FOR UPDATE",pid))existing.put(s(row,"LINE_KEY"),row);var keys=new HashSet<String>();BigDecimal total=BigDecimal.ZERO;
  for(var line:p.lines()){require(keys.add(line.lineKey()),400,"ERP订单行重复");require(line.dueDate().getYear()>=2000&&line.dueDate().getYear()<=2100,400,"ERP交期范围无效");total=total.add(line(line.quantity(),line.unitPrice()));var previous=existing.get(line.lineKey());if(previous!=null){BigDecimal shipped=shipped(s(previous,"ID")),received=received(s(previous,"ID"));require(line.quantity().compareTo(shipped.max(received))>=0,409,"ERP数量低于已发或实收，须业务纠正");if(shipped.signum()>0)require(line.material().equals(previous.get("MATERIAL")),409,"已发运行不能更换物料");}if(!supplier.status().equals("QUALIFIED")){require(previous!=null&&line.quantity().compareTo(x.decimal(previous.get("QUANTITY")))<=0&&line.unitPrice().compareTo(x.clearAmount(previous,"UNIT_PRICE_CIPHER"))<=0,409,"冻结或淘汰供方不能扩大采购承诺");}}
  require(total.signum()>0,400,"订单总额须大于零");money(total);for(var oldLine:existing.values())if(!keys.contains(s(oldLine,"LINE_KEY")))require(shipped(s(oldLine,"ID")).signum()==0,409,"已有发运的物料行不能移除");
  if(fresh){try{x.db.update("INSERT INTO SRM_COL_PO(ID,ORG_ID,SUPPLIER_ID,CONNECTOR_ID,MODE,EXTERNAL_KEY,PO_NO,CURRENCY,SOURCE_VERSION,STATUS,CANCELLED,CREATED_BY,CREATED_AT,UPDATED_AT) VALUES(?,?,?,?,?,?,?,?,?,'WAIT_CONFIRM',?,?,NOW(3),NOW(3))",pid,origin.orgId(),sid,origin.connectorId(),origin.mode(),event.businessKey(),p.poNo(),p.currency(),event.version(),p.cancelled(),origin.operatorId());}catch(org.springframework.dao.DuplicateKeyException e){throw new CommonException(409,"订单编号已被其他来源使用");}}else x.db.update("UPDATE SRM_COL_PO SET CURRENCY=?,SOURCE_VERSION=?,CONFIRMED_VERSION=0,CANCELLED=? WHERE ID=?",p.currency(),event.version(),p.cancelled(),pid);
  for(var line:p.lines()){var previous=existing.get(line.lineKey());if(previous==null)x.db.update("INSERT INTO SRM_COL_PO_LINE(ID,PO_ID,LINE_KEY,MATERIAL,QUANTITY,UNIT_PRICE_CIPHER,DUE_DATE,ACTIVE) VALUES(?,?,?,?,?,?,?,true)",id(),pid,line.lineKey(),line.material(),line.quantity(),x.crypto.encrypt(line.unitPrice().toPlainString()),line.dueDate());else x.db.update("UPDATE SRM_COL_PO_LINE SET MATERIAL=?,QUANTITY=?,UNIT_PRICE_CIPHER=?,DUE_DATE=?,ACTIVE=true WHERE ID=?",line.material(),line.quantity(),x.crypto.encrypt(line.unitPrice().toPlainString()),line.dueDate(),previous.get("ID"));}
  for(var line:existing.values())if(!keys.contains(s(line,"LINE_KEY")))x.db.update("UPDATE SRM_COL_PO_LINE SET ACTIVE=false WHERE ID=?",line.get("ID"));
  x.db.update("INSERT INTO SRM_COL_PO_HISTORY(ID,PO_ID,SOURCE_VERSION,PAYLOAD_CIPHER,CREATED_AT) VALUES(?,?,?,?,NOW(3))",id(),pid,event.version(),x.crypto.encrypt(x.json(p)));x.db.update("UPDATE SRM_COL_PO_CHANGE SET STATUS=CASE WHEN ID=? THEN 'APPLIED' ELSE 'SUPERSEDED' END,CLOSED_AT=NOW(3) WHERE PO_ID=? AND STATUS='PENDING'",p.changeRequestId(),pid);x.db.update("UPDATE SRM_COL_RISK_EVENT SET STATUS='SUPERSEDED',UPDATED_AT=NOW(3) WHERE PO_ID=? AND KIND='DELIVERY_OVERDUE' AND STATUS='PENDING_ASSESSMENT'",pid);x.refreshPo(pid);var po=x.po(a,pid,false);x.notifyBoth(po,pid,fresh?"PO_IMPORTED":"PO_CHANGED",fresh?"收到新的采购订单，请核对交期数量":"ERP订单已变更，请核对新版本并重新确认",pid+":"+event.version());x.audit(a,sid,pid,fresh?"PO_IMPORTED":"PO_SOURCE_UPDATED",Map.of("sourceVersion",event.version(),"mode",origin.mode(),"eventId",event.eventId()));return Map.of("id",pid);
 }
 BigDecimal shipped(String line){return x.db.queryForObject("SELECT COALESCE(SUM(l.QUANTITY),0) FROM SRM_COL_ASN_LINE l JOIN SRM_COL_ASN a ON a.ID=l.ASN_ID WHERE l.PO_LINE_ID=? AND a.STATUS<>'WITHDRAWN'",BigDecimal.class,line);}
 BigDecimal received(String line){return x.db.queryForObject("SELECT COALESCE(SUM(l.QUANTITY),0) FROM SRM_COL_RECEIPT_LINE l JOIN SRM_COL_RECEIPT r ON r.ID=l.RECEIPT_ID WHERE l.PO_LINE_ID=? AND r.STATUS='POSTED'",BigDecimal.class,line);}
 public Map<String,Object> page(Context a,int current,int size,String search,String status){return page(a,current,size,search,status,"");}
 public Map<String,Object> page(Context a,int current,int size,String search,String status,String supplierId){x.readable(a);require(current>=1&&size>=1&&size<=100,400,"分页范围无效");var args=new ArrayList<Object>();String where=x.where(a,args,"p");if(supplierId!=null&&!supplierId.isBlank()){x.access.requireSupplier(a,supplierId,false);where+=" AND p.SUPPLIER_ID=?";args.add(supplierId);}if(!search.isBlank()){where+=" AND (p.PO_NO LIKE ? OR s.NAME LIKE ?)";args.add("%"+search+"%");args.add("%"+search+"%");}if(!status.isBlank()){where+=" AND p.STATUS=?";args.add(status);}long count=x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_PO p JOIN SRM_SUPPLIER s ON s.ID=p.SUPPLIER_ID WHERE "+where,Long.class,args.toArray());args.add(size);args.add((current-1)*size);return Map.of("total",count,"records",x.db.queryForList("SELECT p.ID AS id,p.SUPPLIER_ID AS supplierId,p.PO_NO AS poNo,p.STATUS AS status,p.MODE AS mode,p.SOURCE_VERSION AS sourceVersion,p.ROW_VERSION AS rowVersion,p.CURRENCY AS currency,s.NAME AS supplierName FROM SRM_COL_PO p JOIN SRM_SUPPLIER s ON s.ID=p.SUPPLIER_ID WHERE "+where+" ORDER BY p.CREATED_AT DESC,p.ID DESC LIMIT ? OFFSET ?",args.toArray()));}
 public Map<String,Object> detail(Context a,String id){var p=x.po(a,id,false);var out=x.basic(p,new String[][]{{"id","ID"},{"poNo","PO_NO"},{"supplierId","SUPPLIER_ID"},{"mode","MODE"},{"status","STATUS"},{"currency","CURRENCY"},{"sourceVersion","SOURCE_VERSION"},{"rowVersion","ROW_VERSION"},{"confirmedVersion","CONFIRMED_VERSION"}});var lines=new ArrayList<Map<String,Object>>();BigDecimal total=BigDecimal.ZERO;for(var l:x.db.queryForList("SELECT * FROM SRM_COL_PO_LINE WHERE PO_ID=? AND ACTIVE=true ORDER BY LINE_KEY",id)){var item=x.basic(l,new String[][]{{"id","ID"},{"lineKey","LINE_KEY"},{"material","MATERIAL"},{"quantity","QUANTITY"},{"dueDate","DUE_DATE"}});BigDecimal price=x.clearAmount(l,"UNIT_PRICE_CIPHER"),amount=line(x.decimal(l.get("QUANTITY")),price);if(x.price(a))item.put("unitPrice",price);item.put("amount",amount);item.put("shippedQuantity",shipped(s(l,"ID")));item.put("receivedQuantity",received(s(l,"ID")));total=total.add(amount);lines.add(item);}out.put("lines",lines);out.put("amount",total);out.put("canViewUnitPrice",x.price(a));out.put("changes",changes(a,id));out.put("asns",shipments(a,id));out.put("mes",x.db.queryForList("SELECT m.PRIORITY AS priority,m.SOURCE_REF AS sourceRef,m.SOURCE_VERSION AS version,m.UPDATED_AT AS updatedAt,c.MODE AS mode FROM SRM_COL_MES m JOIN SRM_XCH_CONNECTOR c ON c.ID=m.CONNECTOR_ID WHERE m.PO_ID=?",id));out.put("history",x.db.queryForList("SELECT SOURCE_VERSION AS sourceVersion,CREATED_AT AS createdAt FROM SRM_COL_PO_HISTORY WHERE PO_ID=? ORDER BY SOURCE_VERSION DESC",id));return out;}
 public Map<String,Object> confirm(Context a,String id,Confirmation p){x.shipper(a);var order=x.lockPo(a,id);x.version(order,p.rowVersion());require(!Boolean.TRUE.equals(order.get("CANCELLED"))&&Set.of("WAIT_CONFIRM","CONFIRMED","SHIPPING").contains(s(order,"STATUS")),409,"订单当前不能确认");x.db.update("UPDATE SRM_COL_PO SET CONFIRMED_VERSION=SOURCE_VERSION WHERE ID=?",id);x.refreshPo(id);x.audit(a,a.supplierId(),id,"PO_SUPPLIER_CONFIRMED",Map.of("sourceVersion",order.get("SOURCE_VERSION"),"comment",p.comment()));x.notice(order,"BUYER",id,"PO_CONFIRMED","供应商已确认订单交期和数量",id+":confirmed:"+order.get("SOURCE_VERSION"));return detail(a,id);}
 public List<Map<String,Object>> changes(Context a,String id){x.po(a,id,false);var out=new ArrayList<Map<String,Object>>();for(var row:x.db.queryForList("SELECT * FROM SRM_COL_PO_CHANGE WHERE PO_ID=? ORDER BY CREATED_AT DESC",id)){var item=x.basic(row,new String[][]{{"id","ID"},{"status","STATUS"},{"baseVersion","BASE_VERSION"},{"createdAt","CREATED_AT"}});item.put("proposal",x.object(x.crypto.decrypt(s(row,"PROPOSAL_CIPHER"))));out.add(item);}return out;}
 public Map<String,Object> change(Context a,String id,Change p){x.shipper(a);var order=x.lockPo(a,id);String hash=x.hash(p);var prior=x.db.queryForList("SELECT * FROM SRM_COL_PO_CHANGE WHERE PO_ID=? AND REQUEST_KEY=?",id,p.requestKey());if(!prior.isEmpty()){require(hash.equals(prior.get(0).get("REQUEST_HASH")),409,"变更请求键内容冲突");return detail(a,id);}x.version(order,p.rowVersion());require(!Boolean.TRUE.equals(order.get("CANCELLED"))&&!s(order,"STATUS").equals("RECEIVED"),409,"此订单不能申请交期数量变更");require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_PO_CHANGE WHERE PO_ID=? AND STATUS='PENDING'",Long.class,id)==0,409,"已有待ERP处理变更");var active=x.db.queryForList("SELECT ID FROM SRM_COL_PO_LINE WHERE PO_ID=? AND ACTIVE=true",String.class,id);require(p.lines().size()==active.size()&&new HashSet<>(p.lines().stream().map(ProposedLine::lineId).toList()).equals(new HashSet<>(active)),400,"变更须包含当前所有物料行");for(var l:p.lines())require(l.quantity().compareTo(shipped(l.lineId()).max(received(l.lineId())))>=0,409,"建议数量不能低于已发/实收");String cid=id();x.db.update("INSERT INTO SRM_COL_PO_CHANGE(ID,PO_ID,BASE_VERSION,STATUS,PREVIOUS_STATUS,PROPOSAL_CIPHER,REQUEST_KEY,REQUEST_HASH,CREATED_BY,CREATED_AT) VALUES(?,?,?,'PENDING',?,?,?,?,?,NOW(3))",cid,id,order.get("SOURCE_VERSION"),order.get("STATUS"),x.crypto.encrypt(x.json(p)),p.requestKey(),hash,a.userId());var payload=new LinkedHashMap<String,Object>();payload.put("poNo",order.get("PO_NO"));payload.put("sourceKey",order.get("EXTERNAL_KEY"));payload.put("changeRequestId",cid);payload.put("baseVersion",order.get("SOURCE_VERSION"));payload.put("reason",p.reason());payload.put("lines",p.lines().stream().map(l->Map.of("lineKey",x.db.queryForObject("SELECT LINE_KEY FROM SRM_COL_PO_LINE WHERE ID=?",String.class,l.lineId()),"quantity",l.quantity(),"dueDate",l.dueDate())).toList());x.exchange.enqueue(s(order,"ORG_ID"),"ERP",s(order,"MODE"),"PO_CHANGE_REQUEST",cid,1,payload,a.userId());x.refreshPo(id);x.audit(a,a.supplierId(),cid,"PO_CHANGE_REQUESTED",Map.of("poId",id,"baseVersion",order.get("SOURCE_VERSION")));return detail(a,id);}
 public Map<String,Object> changeResult(Origin o,Command e){String id=String.valueOf(e.data().get("changeRequestId"));require(id.equals(e.businessKey()),400,"变更回执业务键不一致");var rows=x.db.queryForList("SELECT PO_ID FROM SRM_COL_PO_CHANGE WHERE ID=?",id);if(rows.isEmpty())throw new PendingDependency("PO_CHANGE_NOT_FOUND");var a=x.system(o);var po=x.lockPo(a,s(rows.get(0),"PO_ID"));require(o.connectorId().equals(po.get("CONNECTOR_ID")),403,"变更回执来源不匹配");String result=String.valueOf(e.data().get("result"));require(result.equals("REJECTED"),400,"变更批准必须通过正式PO新版本回写");x.db.update("UPDATE SRM_COL_PO_CHANGE SET STATUS='REJECTED',CLOSED_AT=NOW(3) WHERE ID=? AND STATUS='PENDING'",id);x.refreshPo(s(po,"ID"));x.notifyBoth(po,id,"PO_CHANGE_REJECTED","ERP未接受本次订单变更，请查看原有效订单",id+":rejected");x.audit(a,s(po,"SUPPLIER_ID"),id,"ERP_PO_CHANGE_REJECTED",Map.of("eventId",e.eventId()));return Map.of("id",id);}
 public Map<String,Object> shipment(Context a,String pid,Shipment p){x.shipper(a);var po=x.lockPo(a,pid);String hash=x.hash(p);var old=x.db.queryForList("SELECT ID,REQUEST_HASH FROM SRM_COL_ASN WHERE PO_ID=? AND REQUEST_KEY=?",pid,p.requestKey());if(!old.isEmpty()){require(hash.equals(old.get(0).get("REQUEST_HASH")),409,"ASN请求内容冲突");return asn(a,s(old.get(0),"ID"));}x.version(po,p.rowVersion());require(n(po,"CONFIRMED_VERSION")==n(po,"SOURCE_VERSION")&&Set.of("CONFIRMED","SHIPPING").contains(s(po,"STATUS")),409,"须先确认当前PO版本，且不能有待处理变更或已取消");var totals=new HashMap<String,BigDecimal>();for(var l:p.lines())totals.merge(l.poLineId(),l.quantity(),BigDecimal::add);for(var entry:totals.entrySet()){var rows=x.db.queryForList("SELECT QUANTITY FROM SRM_COL_PO_LINE WHERE ID=? AND PO_ID=? AND ACTIVE=true",entry.getKey(),pid);require(rows.size()==1,400,"发运行不属于有效订单");require(shipped(entry.getKey()).add(entry.getValue()).compareTo(x.decimal(rows.get(0).get("QUANTITY")))<=0,409,"累计发运不能超过有效订单量");}var policy=x.policy(s(po,"ORG_ID"));String id=id();try{x.db.update("INSERT INTO SRM_COL_ASN(ID,ORG_ID,SUPPLIER_ID,PO_ID,ASN_NO,ETA_MS,CARRIER,TRACKING_NO,STATUS,TOLERANCE_PCT,POLICY_VERSION,CREATED_BY,REQUEST_KEY,REQUEST_HASH,CREATED_AT) VALUES(?,?,?,?,?,?,?,?,'IN_TRANSIT',?,?,?,?,?,NOW(3))",id,po.get("ORG_ID"),po.get("SUPPLIER_ID"),pid,p.asnNo()==null||p.asnNo().isBlank()?"ASN"+id:p.asnNo(),p.eta(),p.carrier(),p.trackingNo(),policy.get("tolerancePct"),policy.get("version"),a.userId(),p.requestKey(),hash);}catch(org.springframework.dao.DuplicateKeyException ex){throw new CommonException(409,"ASN编号已存在");}for(var l:p.lines())x.db.update("INSERT INTO SRM_COL_ASN_LINE(ID,ASN_ID,PO_LINE_ID,BATCH_NO,QUANTITY) VALUES(?,?,?,?,?)",id(),id,l.poLineId(),l.batchNo(),l.quantity());x.refreshPo(pid);x.exchange.enqueue(s(po,"ORG_ID"),"ERP",s(po,"MODE"),"ASN_SUBMITTED",id,1,Map.of("poId",pid,"poNo",po.get("PO_NO"),"asnId",id,"asnNo",p.asnNo()==null||p.asnNo().isBlank()?"ASN"+id:p.asnNo(),"lines",x.db.queryForList("SELECT ID AS asnLineId,PO_LINE_ID AS poLineId,BATCH_NO AS batchNo,QUANTITY AS quantity FROM SRM_COL_ASN_LINE WHERE ASN_ID=?",id)),a.userId());x.notifyBoth(po,id,"ASN_SUBMITTED","供应商已提交发运通知",id+":submitted");x.audit(a,a.supplierId(),id,"ASN_SUBMITTED",Map.of("poId",pid,"lineCount",p.lines().size()));return asn(a,id);}
 public List<Map<String,Object>> shipments(Context a,String pid){x.po(a,pid,false);return x.db.queryForList("SELECT ID AS id,ASN_NO AS asnNo,STATUS AS status,ETA_MS AS eta,CARRIER AS carrier,TRACKING_NO AS trackingNo,DIFF_FLAG AS diffFlag,ROW_VERSION AS rowVersion FROM SRM_COL_ASN WHERE PO_ID=? ORDER BY CREATED_AT DESC",pid);}
 public Map<String,Object> asn(Context a,String id){var rows=x.db.queryForList("SELECT * FROM SRM_COL_ASN WHERE ID=?",id);require(rows.size()==1,404,"ASN不存在");var r=rows.get(0);x.po(a,s(r,"PO_ID"),false);var out=x.basic(r,new String[][]{{"id","ID"},{"poId","PO_ID"},{"asnNo","ASN_NO"},{"status","STATUS"},{"rowVersion","ROW_VERSION"},{"eta","ETA_MS"},{"carrier","CARRIER"},{"trackingNo","TRACKING_NO"},{"diffFlag","DIFF_FLAG"},{"tolerancePct","TOLERANCE_PCT"},{"policyVersion","POLICY_VERSION"}});var lines=x.db.queryForList("SELECT l.ID AS id,l.PO_LINE_ID AS poLineId,l.BATCH_NO AS batchNo,l.QUANTITY AS quantity,p.MATERIAL AS material FROM SRM_COL_ASN_LINE l JOIN SRM_COL_PO_LINE p ON p.ID=l.PO_LINE_ID WHERE l.ASN_ID=? ORDER BY l.ID",id);for(var line:lines)line.put("receivedQuantity",asnReceived(String.valueOf(line.get("id"))));out.put("lines",lines);out.put("receipts",receiptsForAsn(a,id));return out;}
 public Map<String,Object> tracking(Context a,String id,Tracking p){x.shipper(a);var first=x.db.queryForMap("SELECT PO_ID FROM SRM_COL_ASN WHERE ID=?",id);var po=x.lockPo(a,s(first,"PO_ID"));var asn=x.db.queryForMap("SELECT * FROM SRM_COL_ASN WHERE ID=? FOR UPDATE",id);x.version(asn,p.rowVersion());require(!s(asn,"STATUS").equals("RECEIVED"),409,"已收货发运记录不可静默改写物流信息");x.db.update("UPDATE SRM_COL_ASN SET ETA_MS=?,CARRIER=?,TRACKING_NO=?,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",p.eta(),p.carrier(),p.trackingNo(),id);x.audit(a,a.supplierId(),id,"ASN_TRACKING_UPDATED",Map.of("poId",po.get("ID")));return asn(a,id);}
 BigDecimal asnReceived(String line){return x.db.queryForObject("SELECT COALESCE(SUM(l.QUANTITY),0) FROM SRM_COL_RECEIPT_LINE l JOIN SRM_COL_RECEIPT r ON r.ID=l.RECEIPT_ID WHERE l.ASN_LINE_ID=? AND r.STATUS='POSTED'",BigDecimal.class,line);}
 public Map<String,Object> receive(Context a,String aid,Receipt p){x.buyer(a);var head=x.db.queryForList("SELECT PO_ID FROM SRM_COL_ASN WHERE ID=?",aid);require(head.size()==1,404,"ASN不存在");var po=x.lockPo(a,s(head.get(0),"PO_ID"));return recordReceipt(a,po,aid,p,null,null,0);}
 Map<String,Object> recordReceipt(Context a,Map<String,Object> po,String aid,Receipt p,String connector,String externalKey,long sourceVersion){String hash=x.hash(p);var prior=x.db.queryForList("SELECT ID,REQUEST_HASH FROM SRM_COL_RECEIPT WHERE ORG_ID=? AND REQUEST_KEY=?",po.get("ORG_ID"),p.requestKey());if(!prior.isEmpty()){require(hash.equals(prior.get(0).get("REQUEST_HASH")),409,"收货请求键内容冲突");return Map.of("id",prior.get(0).get("ID"),"replayed",true);}var asn=x.db.queryForMap("SELECT * FROM SRM_COL_ASN WHERE ID=? AND PO_ID=? FOR UPDATE",aid,po.get("ID"));x.version(asn,p.rowVersion());require(Set.of("IN_TRANSIT","PARTIAL").contains(s(asn,"STATUS")),409,"发运已经关闭，不能新增收货");long at=p.receivedAt()==0?x.now():p.receivedAt();require(at<=x.now()+300000&&at>=946656000000L,400,"实收时间范围无效");Set<String> ids=new HashSet<>();var lines=new ArrayList<Map<String,Object>>();for(var l:p.lines()){require(ids.add(l.asnLineId()),400,"实收物料行重复");var candidates=x.db.queryForList("SELECT a.PO_LINE_ID,p.UNIT_PRICE_CIPHER FROM SRM_COL_ASN_LINE a JOIN SRM_COL_PO_LINE p ON p.ID=a.PO_LINE_ID WHERE a.ID=? AND a.ASN_ID=?",l.asnLineId(),aid);require(candidates.size()==1,400,"实收物料行不属于ASN");lines.add(candidates.get(0));}String id=id();try{x.db.update("INSERT INTO SRM_COL_RECEIPT(ID,ORG_ID,SUPPLIER_ID,PO_ID,ASN_ID,RECEIPT_NO,CONNECTOR_ID,EXTERNAL_KEY,SOURCE_VERSION,FINAL_RECEIPT,STATUS,RECEIVED_MS,CREATED_BY,CREATED_AT,REQUEST_KEY,REQUEST_HASH) VALUES(?,?,?,?,?,?,?,?,?,?,'POSTED',?,?,NOW(3),?,?)",id,po.get("ORG_ID"),po.get("SUPPLIER_ID"),po.get("ID"),aid,p.receiptNo()==null||p.receiptNo().isBlank()?"RCV"+id:p.receiptNo(),connector,externalKey,sourceVersion,p.finalReceipt(),at,a.userId(),p.requestKey(),hash);}catch(org.springframework.dao.DuplicateKeyException e){throw new CommonException(409,"收货编号或来源记录已存在");}for(int i=0;i<p.lines().size();i++){var l=p.lines().get(i);var basis=lines.get(i);BigDecimal amount=line(l.quantity(),x.clearAmount(basis,"UNIT_PRICE_CIPHER"));x.db.update("INSERT INTO SRM_COL_RECEIPT_LINE(ID,RECEIPT_ID,ASN_LINE_ID,PO_LINE_ID,QUANTITY,UNIT_PRICE_CIPHER,AMOUNT_CIPHER,PO_VERSION) VALUES(?,?,?,?,?,?,?,?)",id(),id,l.asnLineId(),basis.get("PO_LINE_ID"),l.quantity(),basis.get("UNIT_PRICE_CIPHER"),x.crypto.encrypt(amount.toPlainString()),po.get("SOURCE_VERSION"));}refreshAsn(po,asn,p.finalReceipt());x.refreshPo(s(po,"ID"));x.notifyBoth(po,id,"RECEIPT_POSTED","实收记录已登记，请核对数量差异",id+":posted");x.audit(a,s(po,"SUPPLIER_ID"),id,"RECEIPT_POSTED",Map.of("asnId",aid,"finalReceipt",p.finalReceipt(),"source",connector==null?"MANUAL":connector));return Map.of("id",id,"replayed",false);}
 void refreshAsn(Map<String,Object> po,Map<String,Object> asn,boolean close){boolean diff=false;for(var line:x.db.queryForList("SELECT ID,QUANTITY FROM SRM_COL_ASN_LINE WHERE ASN_ID=?",asn.get("ID"))){BigDecimal actual=asnReceived(s(line,"ID")),expected=x.decimal(line.get("QUANTITY"));if(differs(expected,actual,x.decimal(asn.get("TOLERANCE_PCT")),close))diff=true;}x.db.update("UPDATE SRM_COL_ASN SET STATUS=?,DIFF_FLAG=?,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",close?"RECEIVED":"PARTIAL",diff?"DIFFERENCE":"NORMAL",asn.get("ID"));if(diff){String key="tolerance:"+asn.get("ID");x.risk(po,"QUANTITY_TOLERANCE",key,Map.of("asnId",asn.get("ID"),"tolerancePct",asn.get("TOLERANCE_PCT"),"policyVersion",asn.get("POLICY_VERSION")));x.notifyBoth(po,s(asn,"ID"),"QUANTITY_DIFFERENCE","实收超出容差，请核对差异",key);}else if(close)x.db.update("UPDATE SRM_COL_RISK_EVENT SET STATUS='RESOLVED',UPDATED_AT=NOW(3) WHERE EVENT_KEY=?", "tolerance:"+asn.get("ID"));}
 public Map<String,Object> sourceReceipt(Origin o,Command event){SourceReceipt p=x.input(event.data(),SourceReceipt.class);var rows=x.db.queryForList("SELECT a.ID,a.PO_ID FROM SRM_COL_ASN a JOIN SRM_COL_PO p ON p.ID=a.PO_ID WHERE a.ORG_ID=? AND a.ASN_NO=? AND p.CONNECTOR_ID=?",o.orgId(),p.asnNo(),o.connectorId());if(rows.isEmpty())throw new PendingDependency("ASN_NOT_FOUND");Context a=x.system(o);var po=x.lockPo(a,s(rows.get(0),"PO_ID"));var prior=x.db.queryForList("SELECT * FROM SRM_COL_RECEIPT WHERE CONNECTOR_ID=? AND EXTERNAL_KEY=? ORDER BY SOURCE_VERSION DESC LIMIT 1",o.connectorId(),event.businessKey());if(!prior.isEmpty()){var r=prior.get(0);require(event.version()==n(r,"SOURCE_VERSION")+1,409,"收货来源版本冲突");require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_RECEIPT_LINE WHERE RECEIPT_ID=? AND ALLOC_RECON_ID IS NOT NULL",Long.class,r.get("ID"))==0,409,"已占用对账的收货不能静默重写，须业务纠正");require(s(r,"ASN_ID").equals(rows.get(0).get("ID"))&&s(r,"RECEIPT_NO").equals(p.receiptNo()),409,"收货不能改绑ASN或收货号");x.db.update("UPDATE SRM_COL_RECEIPT SET STATUS='SUPERSEDED',ACTIVE_MARK=NULL WHERE ID=?",r.get("ID"));x.db.update("UPDATE SRM_COL_ASN SET STATUS='PARTIAL' WHERE ID=?",r.get("ASN_ID"));}var asn=x.db.queryForMap("SELECT * FROM SRM_COL_ASN WHERE ID=?",rows.get(0).get("ID"));Receipt input=new Receipt("erp:"+cn.hutool.crypto.digest.DigestUtil.sha256Hex(event.eventId()).substring(0,60),p.receiptNo(),n(asn,"ROW_VERSION"),p.receivedAt(),p.finalReceipt(),p.lines());return recordReceipt(a,po,s(asn,"ID"),input,o.connectorId(),event.businessKey(),event.version());}
 public List<Map<String,Object>> receiptsForAsn(Context a,String aid){var rows=x.db.queryForList("SELECT PO_ID FROM SRM_COL_ASN WHERE ID=?",aid);require(rows.size()==1,404,"ASN不存在");x.po(a,s(rows.get(0),"PO_ID"),false);return x.db.queryForList("SELECT ID AS id,RECEIPT_NO AS receiptNo,STATUS AS status,FINAL_RECEIPT AS finalReceipt,RECEIVED_MS AS receivedAt,ROW_VERSION AS rowVersion FROM SRM_COL_RECEIPT WHERE ASN_ID=? ORDER BY CREATED_AT DESC",aid);}
 public List<Map<String,Object>> receipts(Context a,String supplierId){x.buyer(a);var args=new ArrayList<Object>();String where=x.where(a,args,"r");if(!supplierId.isBlank()){where+=" AND r.SUPPLIER_ID=?";args.add(supplierId);}var rows=x.db.queryForList("SELECT l.ID,l.QUANTITY,l.AMOUNT_CIPHER,l.UNIT_PRICE_CIPHER,l.ALLOC_RECON_ID,r.ID AS RECEIPT_ID,r.RECEIPT_NO,p.PO_NO,p.CURRENCY,p.MODE,s.NAME AS SUPPLIER_NAME,r.SUPPLIER_ID,a.BATCH_NO,pl.MATERIAL FROM SRM_COL_RECEIPT_LINE l JOIN SRM_COL_RECEIPT r ON r.ID=l.RECEIPT_ID JOIN SRM_COL_PO p ON p.ID=r.PO_ID JOIN SRM_COL_ASN_LINE a ON a.ID=l.ASN_LINE_ID JOIN SRM_COL_PO_LINE pl ON pl.ID=l.PO_LINE_ID JOIN SRM_SUPPLIER s ON s.ID=r.SUPPLIER_ID WHERE r.STATUS='POSTED' AND "+where+" ORDER BY r.CREATED_AT DESC,l.ID LIMIT 500",args.toArray());var out=new ArrayList<Map<String,Object>>();for(var row:rows){var item=x.basic(row,new String[][]{{"id","ID"},{"receiptId","RECEIPT_ID"},{"receiptNo","RECEIPT_NO"},{"quantity","QUANTITY"},{"allocatedReconciliation","ALLOC_RECON_ID"},{"poNo","PO_NO"},{"currency","CURRENCY"},{"mode","MODE"},{"supplierName","SUPPLIER_NAME"},{"supplierId","SUPPLIER_ID"},{"batchNo","BATCH_NO"},{"material","MATERIAL"}});item.put("amount",x.clearAmount(row,"AMOUNT_CIPHER"));if(x.price(a))item.put("unitPrice",x.clearAmount(row,"UNIT_PRICE_CIPHER"));out.add(item);}return out;}
 public Map<String,Object> policy(Context a){x.buyer(a);return x.policy(a.orgId());}
 public Map<String,Object> policy(Context a,Policy p){require(!a.portal()&&x.has(a,"CAT-MGR","superAdmin"),403,"仅采购经理可发布容差版本");x.db.update("INSERT IGNORE INTO SRM_COL_POLICY_HEAD(ORG_ID,VERSION) VALUES(?,0)",a.orgId());long current=x.db.queryForObject("SELECT VERSION FROM SRM_COL_POLICY_HEAD WHERE ORG_ID=? FOR UPDATE",Long.class,a.orgId());require(current==p.expectedVersion(),409,"容差版本已变化");x.db.update("INSERT INTO SRM_COL_POLICY(ID,ORG_ID,VERSION,TOLERANCE_PCT,REASON,CREATED_BY,CREATED_AT) VALUES(?,?,?,?,?,?,NOW(3))",id(),a.orgId(),current+1,p.tolerancePct(),p.reason(),a.userId());x.db.update("UPDATE SRM_COL_POLICY_HEAD SET VERSION=VERSION+1 WHERE ORG_ID=?",a.orgId());return x.policy(a.orgId());}
 public Map<String,Object> dashboard(Context a){x.readable(a);var args=new ArrayList<Object>();String where=x.where(a,args,"p");var data=x.db.queryForList("SELECT p.*,s.NAME AS SUPPLIER_NAME FROM SRM_COL_PO p JOIN SRM_SUPPLIER s ON s.ID=p.SUPPLIER_ID WHERE "+where+" ORDER BY p.UPDATED_AT DESC LIMIT 1000",args.toArray());BigDecimal transit=BigDecimal.ZERO,received=BigDecimal.ZERO,late=BigDecimal.ZERO;var rows=new ArrayList<Map<String,Object>>();for(var p:data){BigDecimal orderTransit=BigDecimal.ZERO,orderReceived=BigDecimal.ZERO,orderLate=BigDecimal.ZERO;for(var line:x.db.queryForList("SELECT * FROM SRM_COL_PO_LINE WHERE PO_ID=? AND ACTIVE=true",p.get("ID"))){BigDecimal got=received(s(line,"ID"));orderReceived=orderReceived.add(got);orderTransit=orderTransit.add(shipped(s(line,"ID")).subtract(got).max(BigDecimal.ZERO));if(!Boolean.TRUE.equals(p.get("CANCELLED"))&&LocalDate.parse(s(line,"DUE_DATE")).isBefore(x.today()))orderLate=orderLate.add(x.decimal(line.get("QUANTITY")).subtract(got).max(BigDecimal.ZERO));}var r=x.basic(p,new String[][]{{"poId","ID"},{"poNo","PO_NO"},{"supplierId","SUPPLIER_ID"},{"supplierName","SUPPLIER_NAME"},{"mode","MODE"},{"status","STATUS"}});r.put("inTransit",orderTransit);r.put("received",orderReceived);r.put("overdue",orderLate);r.put("priorities",x.db.queryForList("SELECT PRIORITY AS priority,SOURCE_REF AS sourceRef FROM SRM_COL_MES WHERE PO_ID=?",p.get("ID")));rows.add(r);transit=transit.add(orderTransit);received=received.add(orderReceived);late=late.add(orderLate);}return Map.of("rows",rows,"inTransit",transit,"received",received,"overdue",late,"truncated",data.size()==1000);}
 @Scheduled(fixedDelay=30000) public void overdue(){for(var p:x.db.queryForList("SELECT p.* FROM SRM_COL_PO p WHERE p.CANCELLED=false AND EXISTS(SELECT 1 FROM SRM_COL_PO_LINE l WHERE l.PO_ID=p.ID AND l.ACTIVE=true AND l.DUE_DATE<?) ORDER BY p.SUPPLIER_ID,p.ID LIMIT 200",x.today())){var context=new Context(s(p,"CREATED_BY"),s(p,"ORG_ID"),null,Set.of("BUYER","SYSTEM"),false,Set.of(s(p,"ORG_ID")),false,false);p=x.lockPo(context,s(p,"ID"));if(Boolean.TRUE.equals(p.get("CANCELLED")))continue;for(var line:x.db.queryForList("SELECT * FROM SRM_COL_PO_LINE WHERE PO_ID=? AND ACTIVE=true AND DUE_DATE<?",p.get("ID"),x.today())){String key="late:"+line.get("ID")+":"+line.get("DUE_DATE");BigDecimal remaining=x.decimal(line.get("QUANTITY")).subtract(received(s(line,"ID")));if(remaining.signum()>0){x.risk(p,"DELIVERY_OVERDUE",key,Map.of("poLineId",line.get("ID"),"dueDate",String.valueOf(line.get("DUE_DATE")),"remaining",remaining));x.notifyBoth(p,s(p,"ID"),"DELIVERY_OVERDUE","采购订单已逾期未收完，请跟进交付",key);}else x.db.update("UPDATE SRM_COL_RISK_EVENT SET STATUS='RESOLVED',UPDATED_AT=NOW(3) WHERE EVENT_KEY=?",key);}}}
 public List<Map<String,Object>> notices(Context a){x.readable(a);var args=new ArrayList<Object>();String where=x.where(a,args,"n");where+=a.portal()?" AND n.AUDIENCE='PORTAL'":x.has(a,"FIN")?" AND n.AUDIENCE IN ('BUYER','FIN')":" AND n.AUDIENCE='BUYER'";return x.db.queryForList("SELECT n.ID AS id,n.BUSINESS_ID AS businessId,n.KIND AS kind,n.MESSAGE AS message,n.CREATED_AT AS createdAt FROM SRM_COL_NOTICE n WHERE "+where+" ORDER BY n.CREATED_AT DESC,n.ID DESC LIMIT 100",args.toArray());}
}
